"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21645"],{88151(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.etapa_ordem_duplicada","status":422,"titulo":"Duas etapas do formul\xe1rio t\xeam a mesma ordem"},"descricao":{"codigo":"uniplus.estrutura_formulario.etapa_ordem_duplicada","requisitos":[],"oQueAconteceu":["Duas etapas do formul\xe1rio t\xeam o mesmo valor de `ordem`. A ordem define a sequ\xeancia em que o candidato percorre as etapas e \xe9 por ela que a revis\xe3o e aceite se reconhece como a \xfaltima; com ordem repetida a sequ\xeancia n\xe3o ficaria definida. A mensagem \xe9 \\"Duas etapas do formul\xe1rio t\xeam a mesma ordem.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `etapas[i].ordem`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. A entrada aponta a segunda ocorr\xeancia e as seguintes; a primeira fica de fora da recusa.","A estrutura das etapas s\xf3 \xe9 conferida quando todas as etapas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada etapa \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as etapas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as etapas s\xf3 depois que a estrutura das etapas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["D\xea a cada etapa uma `ordem` distinta, em sequ\xeancia crescente, com a revis\xe3o e aceite na maior. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);